template <class CharT, class Traits>

void swap(std::basic_spanstream<CharT, Traits> &lhs,

    std::basic_spanstream<CharT, Traits> &rhs);

examples.code:
#include <spanstream>
#include <utility>
#include <cassert>
#include <iostream>

int main() {
    char buffer[16] = "42";
    std::spanstream stream{std::span<char>{buffer}};
    int value{};
    stream >> value;
    assert(value == 42);
    assert(stream.rdbuf() != nullptr);
    char backup[16]{};
    std::spanstream other{std::span<char>{backup}};
    other = std::move(stream);
    other.swap(stream);
    std::swap(other, stream);
    std::cout << "Checks passed\n";
}
